completionsAPI.nodejs:
import OpenAI from "openai";
import process from 'process';

const openai = new OpenAI({
    apiKey: process.env.DASHSCOPE_API_KEY,
    baseURL: 'https://[workspace-id].cn-beijing.maas.aliyuncs.com/compatible-mode/v1'
});

async function main() {
    const completion = await openai.chat.completions.create({
        model: 'vanchin/deepseek-ocr',
        messages: [
            {
                role: 'user',
                content: [
                    {
                        type: 'image_url',
                        image_url: {
                            url: 'https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20241108/ctdzex/biaozhun.jpg',
                            detail: 'high',
                        },
                    },
                    {
                        type: 'text',
                        text: 'Read all the text in the image.',
                    },
                ],
            },
        ],
    });

    console.log(completion.choices[0].message.content);
}

main();
